public class ShapeUtilities_equal_TriageGen0Test {













    @Test
    public void testEqual_DifferentSegmentsCount() {
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);
        p1.lineTo(10, 10);

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);
        // p2 has an extra segment or different structure to trigger isDone mismatch
        p2.lineTo(10, 10);
        p2.lineTo(20, 20);

        assertFalse(ShapeUtilities.equal(p1, p2));
    }




}

